import{B as e,Q as t,s as n,z as r}from"./chunks/framework.hue4hZNP.js";import"./chunks/admin-wrestler-list.CbKgsY0J.js";var i=JSON.parse(`{"title":"Set a Player-Controlled Wrestler","description":"","frontmatter":{},"headers":[],"relativePath":"guide/set-player-controlled-wrestler.md","filePath":"guide/set-player-controlled-wrestler.md"}`),a={name:`guide/set-player-controlled-wrestler.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="set-a-player-controlled-wrestler" tabindex="-1">Set a Player-Controlled Wrestler <a class="header-anchor" href="#set-a-player-controlled-wrestler" aria-label="Permalink to &quot;Set a Player-Controlled Wrestler&quot;">​</a></h1><p>An admin or booker&#39;s guide to handing a wrestler to a player. A wrestler flagged as <strong>player-controlled</strong> belongs to a real account: that player makes their wrestler&#39;s campaign choices, books their league matches, and gets personal notifications — instead of the AI running them as an NPC.</p><hr><h2 id="step-1-—-open-the-wrestler" tabindex="-1">Step 1 — Open the wrestler <a class="header-anchor" href="#step-1-—-open-the-wrestler" aria-label="Permalink to &quot;Step 1 — Open the wrestler&quot;">​</a></h2><p>Open <strong>Wrestler List</strong> from the navigation and click the wrestler you want to hand over (or create a new one). The edit dialog opens.</p><p><img src="/screenshots/admin-wrestler-list.png" alt="Wrestler list"></p><hr><h2 id="step-2-—-flag-the-wrestler-as-a-player" tabindex="-1">Step 2 — Flag the wrestler as a player <a class="header-anchor" href="#step-2-—-flag-the-wrestler-as-a-player" aria-label="Permalink to &quot;Step 2 — Flag the wrestler as a player&quot;">​</a></h2><p>In the edit dialog:</p><ol><li>Tick <strong>Is Player</strong>.</li><li>A <strong>Player Account</strong> combo appears — pick the account that will control this wrestler. Only players with an account can log in and act as their wrestler.</li><li>Save.</li></ol><p>The roster list shows an <strong>Is Player?</strong> column so you can see at a glance who&#39;s human.</p><hr><h2 id="step-3-—-what-changes-for-a-player-controlled-wrestler" tabindex="-1">Step 3 — What changes for a player-controlled wrestler <a class="header-anchor" href="#step-3-—-what-changes-for-a-player-controlled-wrestler" aria-label="Permalink to &quot;Step 3 — What changes for a player-controlled wrestler&quot;">​</a></h2><ul><li><strong>Player Dashboard</strong> — the player sees their wrestler&#39;s stats, effective stats (with all modifiers applied), status cards, season history, and notifications there.</li><li><strong>Campaign mode</strong> — the player can assign the wrestler to a campaign and make story choices on their behalf; AI-controlled wrestlers never appear in a player&#39;s campaign slot.</li><li><strong>Leagues</strong> — player-controlled wrestlers can be drafted into leagues and their players report match results (see <a href="./report-match-results.html">Report Match Results</a>).</li><li><strong>Tournaments</strong> — player-controlled entrants can appear in brackets; when one of their matches books, they get a notification to report the result.</li></ul><hr><h2 id="step-4-—-take-the-wrestler-back-un-flagging" tabindex="-1">Step 4 — Take the wrestler back (un-flagging) <a class="header-anchor" href="#step-4-—-take-the-wrestler-back-un-flagging" aria-label="Permalink to &quot;Step 4 — Take the wrestler back (un-flagging)&quot;">​</a></h2><p>Untick <strong>Is Player</strong> and save. The link to the player account is cleared — the wrestler returns to AI control. Any campaign or league history stays with the wrestler.</p><blockquote><p>💡 <strong>One account, one wrestler:</strong> the player-account link is exclusive — if an account already controls a wrestler, reassigning it moves control. Clear a wrestler&#39;s flag before handing the account to someone else.</p></blockquote><hr><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./wrestler-profile.html">Wrestler Profile</a> — what players see once they control a wrestler.</li><li><a href="./grow-a-wrestler.html">Grow a Wrestler</a> — fans, tiers, injuries, and the career arc.</li><li><a href="./player-dashboard.html">Player Dashboard</a> — the player&#39;s home screen.</li><li><a href="./report-match-results.html">Report Match Results</a> — the player&#39;s side of league play.</li></ul>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};